```go
package dates

import (
	"errors"
	"strconv"
	"strings"
	"testing"
	"time"
)

func TestParseDate(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want time.Time
	}{
		{"typical date", "2024-03-05", time.Date(2024, time.March, 5, 0, 0, 0, 0, time.UTC)},
		{"leap day", "2024-02-29", time.Date(2024, time.February, 29, 0, 0, 0, 0, time.UTC)},
		{"first day of year", "2001-01-01", time.Date(2001, time.January, 1, 0, 0, 0, 0, time.UTC)},
		{"last day of year", "1999-12-31", time.Date(1999, time.December, 31, 0, 0, 0, 0, time.UTC)},
		{"minimum padded year", "0001-01-01", time.Date(1, time.January, 1, 0, 0, 0, 0, time.UTC)},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.in)
			if err != nil {
				t.Fatalf("parseDate(%q) returned unexpected error: %v", tt.in, err)
			}
			// Equal compares instants, so check the location and clock
			// separately to pin down "midnight UTC".
			if !got.Equal(tt.want) {
				t.Errorf("parseDate(%q) = %v, want %v", tt.in, got, tt.want)
			}
			if loc := got.Location(); loc != time.UTC {
				t.Errorf("parseDate(%q) location = %v, want %v", tt.in, loc, time.UTC)
			}
			if h, m, s := got.Clock(); h != 0 || m != 0 || s != 0 || got.Nanosecond() != 0 {
				t.Errorf("parseDate(%q) time of day = %02d:%02d:%02d.%09d, want midnight",
					tt.in, h, m, s, got.Nanosecond())
			}
		})
	}
}

func TestParseDateInvalid(t *testing.T) {
	tests := []struct {
		name string
		in   string
	}{
		{"empty string", ""},
		{"whitespace only", "   "},
		{"rfc3339 timestamp", "2024-03-05T00:00:00Z"},
		{"trailing text", "2024-03-05 extra"},
		{"leading whitespace", " 2024-03-05"},
		{"slash separators", "2024/03/05"},
		{"unpadded month and day", "2024-3-5"},
		{"two digit year", "24-03-05"},
		{"day out of range", "2023-02-29"},
		{"month out of range", "2024-13-01"},
		{"day-month-year order", "05-03-2024"},
		{"not a date at all", "yesterday"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.in)
			if err == nil {
				t.Fatalf("parseDate(%q) = %v, want error", tt.in, got)
			}
			if !got.IsZero() {
				t.Errorf("parseDate(%q) = %v, want the zero time alongside the error", tt.in, got)
			}
			if q := strconv.Quote(tt.in); !strings.Contains(err.Error(), q) {
				t.Errorf("parseDate(%q) error = %q, want it to mention the input %s", tt.in, err, q)
			}
			var parseErr *time.ParseError
			if !errors.As(err, &parseErr) {
				t.Errorf("parseDate(%q) error = %q, want it to wrap *time.ParseError", tt.in, err)
			}
		})
	}
}

func TestParseDateRoundTrip(t *testing.T) {
	const layout = "2006-01-02"
	start := time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)
	for day := 0; day < 400; day++ {
		in := start.AddDate(0, 0, day).Format(layout)

		got, err := parseDate(in)
		if err != nil {
			t.Fatalf("parseDate(%q) returned unexpected error: %v", in, err)
		}
		if out := got.Format(layout); out != in {
			t.Errorf("parseDate(%q) formatted back to %q", in, out)
		}
	}
}
```

What it locks down, and two things to be aware of:

- **Happy path** checks the instant, that `Location()` is `time.UTC`, and that the clock is exactly midnight — three separate assertions because `Time.Equal` ignores location.
- **Error path** asserts all three parts of the contract: an error is returned, the returned time is the zero value, the message quotes the input, and `%w` really wraps `*time.ParseError` (so callers can `errors.As` it).
- `"2024-3-5"` is expected to *fail*: the zero-padded `01`/`02` layout elements require exactly two digits. If you actually want unpadded input accepted, that case will fail and the layout needs to be `2006-1-2`.
- Since the layout carries no zone, `time.Parse` already returns UTC, so the `t.UTC()` call in the function is a no-op. The tests assert the documented behavior rather than the mechanism, so they'd still pass if you dropped it — but keeping it is the safer read.

