		name string
		in   string
	}{
		{"empty", ""},
		{"slash separators", "2024/03/15"},
		{"US ordering", "03-15-2024"},
		{"unpadded month and day", "2024-3-5"},
		{"day out of range", "2023-02-29"},
		{"month out of range", "2024-13-01"},
		{"trailing time", "2024-03-15T00:00:00Z"},
		{"trailing space", "2024-03-15 "},
		{"leading space", " 2024-03-15"},
		{"not a date", "hello"},
